float rawDepth = DepthTexture.SampleLevel(PointClamp, uv, 0);
float3 centerPosVS = ReconstructViewPosition(uv, rawDepth, InvProjection);

float3 normalWS = DecodeNormal(NormalTexture.SampleLevel(PointClamp, uv, 0));
float3 normalVS = normalize(mul(float4(normalWS, 0.0), View).xyz);

float3 randomDir = NoiseTexture.Sample(LinearWrap, uv * noiseScale).xyz * 2.0 - 1.0;
float3 tangentCandidate = randomDir - normalVS * dot(randomDir, normalVS);

if (dot(tangentCandidate, tangentCandidate) < 1e-4)
    tangentCandidate = abs(normalVS.z) < 0.999
        ? cross(float3(0, 0, 1), normalVS)
        : cross(float3(0, 1, 0), normalVS);

float3 tangent = normalize(tangentCandidate);
float3 bitangent = cross(normalVS, tangent);
float3x3 tbn = float3x3(tangent, bitangent, normalVS);

float3 samplePosVS = centerPosVS + mul(kernel[i], tbn) * radius;

float4 clip = mul(float4(samplePosVS, 1.0), Projection);
if (clip.w <= 0.0) continue;

float2 ndc = clip.xy / clip.w;
float2 sampleUV = ndc * float2(0.5, -0.5) + 0.5;
if (any(sampleUV < 0.0) || any(sampleUV > 1.0)) continue;

float rawSampleDepth = DepthTexture.SampleLevel(PointClamp, sampleUV, 0);
float sceneZ = ReconstructViewPosition(sampleUV, rawSampleDepth, InvProjection).z;

float occluded = sceneZ <= samplePosVS.z - bias ? 1.0 : 0.0;
float rangeWeight = smoothstep(0.0, 1.0, radius / max(abs(centerPosVS.z - sceneZ), 1e-4));
float directionWeight = saturate(dot(normalVS, normalize(samplePosVS - centerPosVS)));

occlusion += occluded * rangeWeight * directionWeight;
weightSum += rangeWeight * directionWeight;
